export type LiveKitNumber = {
    /**
     * PhoneNumber.e164_format from native ListPhoneNumbers, projected according to authorised phone-number visibility. sip.json observed an empty list; synthetic values are not production evidence.
     */
    number: string;
    /**
     * Native PhoneNumber.status symbolic name; null if unavailable.
     */
    status: string | null;
    /**
     * Dispatch rule association(s) from the native phone-number record; an empty observed association means detached, not an unknown rule id.
     */
    ruleIds: Array<string>;
};

/**
 * One source-relative timeline within this call. IDs are call-local and unique. Preserve separate clocks when origins differ; never infer alignment from a zero first offset.
 */
export type Clock = unknown & {
    /**
     * Call-local clock identifier referenced by clockId. It identifies a timeline, not a LiveKit resource.
     */
    id: string;
    /**
     * What zero on this timeline means, only when retained source evidence establishes it. An unknown origin does not erase captured relative positions.
     */
    origin: 'call_start' | 'session_start' | 'recording_start' | 'first_event' | 'trace_start' | 'unknown';
    /**
     * Observed UTC instant corresponding to zero on this clock. Never substitute Call.startedAt or the capture upload time without evidence. Estimates belong in inferred call-start alignment, not an observed anchor.
     */
    originAt: string | null;
    /**
     * Signed offset: call-relative seconds = source-relative seconds + offsetToCallStartSeconds. Divide span startMs by 1000 first. Null means do not align this timeline to the call or another clock. Zero requires evidence too.
     */
    offsetToCallStartSeconds: number | null;
    /**
     * Provenance of offsetToCallStartSeconds only. Observed uses retained alignment evidence; inferred uses an explicitly documented estimate; unknown requires a null offset. originAt may be unknown even when relative alignment is known.
     */
    alignment: 'observed' | 'inferred' | 'unknown';
};

