export type ProjectId = string;

export type ListCallsData = {
    body?: never;
    path: {
        /**
         * Authorised orgId; the server must verify organisation/project ownership before any read.
         */
        orgId: string;
        /**
         * Authorised projectId; the server must verify organisation/project ownership before any read.
         */
        projectId: string;
    };
    query?: {
        /**
         * Page size, 1 to 100; omitted means 25.
         */
        limit?: number;
        /**
         * Opaque nextCursor from prior response.
         */
        cursor?: string;
        /**
         * Snapshot from prior response; required with cursor.
         */
        snapshot?: string;
        /**
         * Inclusive UTC start boundary applied to call startedAt.
         */
        from?: string;
        /**
         * Exclusive UTC end boundary applied to call startedAt.
         */
        to?: string;
        /**
         * Exact room-name filter; may return multiple conversations.
         */
        room?: string;
        /**
         * How the call reached the agent. Repeat to match any listed channel.
         */
        channel?: Array<'phone' | 'web' | 'console' | 'local' | 'unknown'>;
        /**
         * Highest finding severity on the call: high, medium, or none for calls with neither. Repeat to match any.
         */
        issues?: Array<'high' | 'medium' | 'none'>;
        /**
         * Inclusive lower bound on the call's median answer time in milliseconds. Calls with an unknown answer time never match a bound.
         */
        answerMsMin?: number;
        /**
         * Inclusive upper bound on the call's median answer time in milliseconds. Calls with an unknown answer time never match a bound.
         */
        answerMsMax?: number;
        /**
         * Inclusive lower bound on call length in seconds. Unknown lengths never match a bound.
         */
        durationSecondsMin?: number;
        /**
         * Inclusive upper bound on call length in seconds. Unknown lengths never match a bound.
         */
        durationSecondsMax?: number;
        /**
         * Inclusive lower bound on agent turns. Unknown counts never match a bound.
         */
        turnsMin?: number;
        /**
         * Inclusive upper bound on agent turns. Unknown counts never match a bound.
         */
        turnsMax?: number;
        /**
         * Only calls where every listed value is unknown. This is how the console's "is empty" filter reaches the server; an unknown value is never matched as zero.
         */
        unknown?: Array<'answerMs' | 'durationSeconds' | 'turnCount'>;
        /**
         * User tag. Repeat to match calls carrying any listed tag.
         */
        tag?: Array<string>;
        /**
         * true for calls with a retained recording, false for calls without one. Omitted means both.
         */
        recorded?: boolean;
        /**
         * true for archived calls only, false for unarchived only. Omitted means both.
         */
        archived?: boolean;
        /**
         * Sort key, applied on the server before paging. Unknown values sort after known values in both orders; ties break by id. A cursor is bound to the filters, sort and order it was issued for: changing any of them with a cursor is invalid_request.
         */
        sort?: 'startedAt' | 'durationSeconds' | 'turnCount' | 'answerMs' | 'issues';
        /**
         * Sort direction.
         */
        order?: 'asc' | 'desc';
    };
    url: '/api/v1/org/{orgId}/project/{projectId}/calls';
};

